INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (16, 'w.workerID IN (SELECT currentChampion FROM titles WHERE currentChampion IS NOT NULL)', 'Workers', 'Cross-Promo Champions');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (17, 'w.workerID IN (SELECT workerID FROM tournamentMatchWorkers)', 'Workers', 'Tournament Participants');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (18, "w.workerID IN (SELECT DISTINCT workerIDs FROM pws_hof_ai WHERE workerIDs != '')", 'Workers', 'Hall of Fame Inductees');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (19, "c.push='Main Event' AND c.finalised=1", 'Workers', 'Active Main Eventers');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (20, "w.tagExpert=1 AND w.type='Wrestler'", 'Workers', 'Tag Team Specialists');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (21, "w.workerID IN (SELECT sw.contractID FROM stableworkers sw WHERE sw.isLeader='1')", 'Workers', 'Stable Leaders');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (22, "c.contractStartDate >= '2026-01-01' AND c.contractStartDate < '2026-04-01'", 'Workers', 'Future-Dated Roster (Q1 2026)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (23, "c.contractStartDate >= '2026-07-01' AND c.contractStartDate < '2026-10-01'", 'Workers', 'Future-Dated Roster (Q3 2026)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (24, "c.contractStartDate >= '2027-01-01'", 'Workers', 'Future-Dated Roster (2027)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (25, 'w.charisma >= 80', 'Workers', 'High Charisma (80+)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (26, 'w.intimidation >= 80', 'Workers', 'Top Intimidation (80+)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (27, "w.injuryType IS NOT NULL AND w.injuryType != ''", 'Workers', 'Injured Workers');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (28, 'w.isSuspended=1', 'Workers', 'Suspended Workers');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (29, "w.type='Referee' AND w.refereeing >= 70", 'Workers', 'Veteran Referees (ref 70+)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (30, "w.type='Personality' AND w.agent >= 70", 'Workers', 'Top Managers (agent 70+)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (31, "w.canBeOwner=1 AND w.type='Personality'", 'Workers', 'Authority Figures');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (32, "w.isMasked=1 AND w.type='Wrestler'", 'Workers', 'Masked Wrestlers by Style');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (33, 'w.workerID IN (SELECT worker1 FROM relationships WHERE relationship IN (4,6))', 'Workers', 'Cross-Promo Rivalry Workers');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (34, 'w.workerID IN (SELECT worker1 FROM chemistry WHERE chemAsTeam=1)', 'Workers', 'Chemistry Partners (Positive)');
INSERT INTO filters (filterID, filterText, filterType, filterName) VALUES (35, 'w.workerID IN (SELECT c.workerID FROM storylineworkers sw JOIN contracts c ON c.contractID=sw.contractID WHERE sw.storylineID IN (SELECT storylineID FROM storylines WHERE active=1))', 'Workers', 'Storyline Active Workers');
